// The two sample drawings the site offers. They are original synthetic PDFs generated by
// backend/scripts/generate_samples.py (invented parts and numbers, no third-party content) and
// served as static files. Choosing one downloads it in the browser and hands it to the same
// upload path as a file the visitor picked, so it passes the same checks and the same backend
// inspection; nothing about a sample is special-cased or pre-computed.

export interface Sample {
  id: "basic" | "cad";
  file: string;
  title: string;
  summary: string;
  shows: readonly string[];
}

export const SAMPLES: readonly Sample[] = [
  {
    id: "basic",
    file: "blueprintiq-sample-basic.pdf",
    title: "Labelled plate",
    summary: "A plate with four labelled notes: thickness, diameter, length and material.",
    shows: [
      "Labelled measurements checked against the demonstration requirements",
      "One thickness below the demonstration minimum, so one fail and three passes",
    ],
  },
  {
    id: "cad",
    file: "blueprintiq-sample-cad.pdf",
    title: "CAD-style plate",
    summary: "A plate outline with a hole and drawn dimensions, as a CAD export would print them.",
    shows: [
      "Linear, diameter and tolerance dimensions read as written",
      "A stacked tolerance (+0 over -0.2) tied to its value",
      "Dimensions tied to the lines they refer to, and one that cannot be",
    ],
  },
];

export function sampleById(id: string | null): Sample | null {
  return SAMPLES.find((sample) => sample.id === id) ?? null;
}

export const SAMPLE_PATH = "/samples/";

/** Fetch a sample from this site and wrap it as the File a visitor would have chosen. */
export async function loadSample(sample: Sample, fetcher: typeof fetch = fetch): Promise<File> {
  const response = await fetcher(`${SAMPLE_PATH}${sample.file}`);
  if (!response.ok) throw new Error(`sample unavailable (${response.status})`);
  const blob = await response.blob();
  return new File([blob], sample.file, { type: "application/pdf" });
}
